/**
 * Cultivation artwork lookup for the activity panel and the conversation card.
 *
 * The images are embedded as base64 data URLs (art-data.ts, generated by
 * scripts/gen-art-data.mjs) instead of fetched from the host asset route: a
 * running host keeps that route's allowlist in memory, so a rebuilt client used
 * to 404 on every portrait until the whole app restarted. Embedded art ships
 * with the client that renders it.
 *
 * Every built-in 法门 resolves by role id, so a quick-start roster never falls
 * back to a bare initial. Custom roles fall back to a keyword heuristic and,
 * failing that, to the caller's initial-letter badge.
 * @module dsh-agent-teams/client/artwork
 */

import { APP_ICON_BASE64, ART_BASE64 } from './art-data.ts'

/** Inline data URL for one packaged artwork file ('' when the build missed it). */
function art(file: string): string {
  const base64 = ART_BASE64[file]
  return base64 === undefined ? '' : `data:image/png;base64,${base64}`
}

/** Public avatar data URL for a skin catalog entry. */
export function avatarArt(file: string): string { return art(file) }

import { customRoles } from './custom-roles.ts'
import { agencyRole } from '../agency-roles-lite.ts'

/**
 * Role id → one of the eight shipped skin portraits. The hall and the roster
 * cycle twenty duties through the same eight faces instead of shipping one
 * image per duty; the mapping keeps related duties together (planning, build,
 * verify, review, design, support, attack).
 */
const ROLE_ART: Readonly<Record<string, string>> = {
  planner: 'avatar-planner.png',
  implementer: 'avatar-implementer.png',
  verifier: 'avatar-verifier.png',
  reviewer: 'avatar-reviewer.png',
  architect: 'avatar-architect.png',
  healer: 'avatar-healer.png',
  demon: 'avatar-demon.png',
  researcher: 'avatar-planner.png',
  analyst: 'avatar-planner.png',
  writer: 'avatar-architect.png',
  documenter: 'avatar-architect.png',
  auditor: 'avatar-verifier.png',
  tester: 'avatar-verifier.png',
  operator: 'avatar-implementer.png',
  frontend: 'avatar-implementer.png',
  backend: 'avatar-implementer.png',
  integrator: 'avatar-implementer.png',
  talisman: 'avatar-healer.png',
  musician: 'avatar-healer.png',
  monk: 'avatar-healer.png',
  beastmaster: 'avatar-demon.png',
  puppeteer: 'avatar-demon.png',
  poisoner: 'avatar-demon.png',
  security: 'avatar-demon.png',
}

/** Selectable skins for custom lineup characters: the same eight cycling portraits. */
export const SKIN_OPTIONS = [
  { id: 'demon', name: '性能工程师', art: art('avatar-demon.png') },
  { id: 'implementer', name: '全栈工程师', art: art('avatar-implementer.png') },
  { id: 'captain', name: '项目负责人', art: art('avatar-captain.png') },
  { id: 'planner', name: '产品经理', art: art('avatar-planner.png') },
  { id: 'verifier', name: 'QA', art: art('avatar-verifier.png') },
  { id: 'reviewer', name: '技术评审', art: art('avatar-reviewer.png') },
  { id: 'architect', name: '架构师', art: art('avatar-architect.png') },
  { id: 'healer', name: '修复工程师', art: art('avatar-healer.png') },
] as const

/** Keyword fallback for custom roles, mapped onto the closest shipped portrait. */
const KEYWORD_ART: ReadonlyArray<readonly [RegExp, string]> = [
  [/数据|分析|推演|指标|analys|metric|data/, 'avatar-planner.png'],
  [/研究|调研|取证|探索|resear|investig|explor/, 'avatar-planner.png'],
  [/\bqa\b|质量|验证|校验|verif|quality/, 'avatar-verifier.png'],
  [/测试|回归|test|regress/, 'avatar-verifier.png'],
  [/实现|开发|工程|代码|编程|engineer|implement|backend|\bapi\b|runtime/, 'avatar-implementer.png'],
  [/架构|设计|边界|architect|design/, 'avatar-architect.png'],
  [/审查|裁断|评审|review|judge/, 'avatar-reviewer.png'],
  [/审计|巡查|安全|风险|audit|secur/, 'avatar-demon.png'],
  [/文档|撰写|写作|书记|docs|writer|spec/, 'avatar-architect.png'],
  [/传道|示例|document|tutorial/, 'avatar-architect.png'],
  [/发布|构建|部署|运维|打包|release|build|deploy|\bops\b/, 'avatar-implementer.png'],
  [/规划|拆解|排程|plan|strateg/, 'avatar-planner.png'],
]

/** Captain skin options: exclusive portraits, defaulting to the project lead. */
export const CAPTAIN_SKIN_ARTS = {
  hongjun: { name: '项目负责人', art: art('avatar-captain.png') },
  pangu: { name: '全栈工程师', art: art('avatar-implementer.png') },
  nuwa: { name: '修复工程师', art: art('avatar-healer.png') },
} as const
export type CaptainSkinId = keyof typeof CAPTAIN_SKIN_ARTS

/** Default captain skin is the project lead portrait. */
export const DEFAULT_CAPTAIN_SKIN: CaptainSkinId = 'hongjun'

/** New app icon (assets/app-icons, embedded as a 64px data URL). */
export const APP_ICON = APP_ICON_BASE64 === '' ? '' : `data:image/png;base64,${APP_ICON_BASE64}`

/** Status action artwork per member activity. */
export const ACTION_ART: Record<'working' | 'idle' | 'unknown', string> = {
  working: art('state-working.png'),
  idle: art('state-idle.png'),
  unknown: art('state-unknown.png'),
}

/**
 * Member artwork URL, or null when no role matches (initial-letter fallback).
 * @param name - the member's display name.
 * @param role - the member's role text.
 * @returns the artwork data URL, or null when unmatched.
 */
export function memberArtUrl(name: string, role: string): string | null {
  const custom = customRoles().find(entry => entry.name === name && entry.skin !== undefined)
  if (custom?.skin !== undefined) {
    const skin = SKIN_OPTIONS.find(option => option.id === custom.skin)
    if (skin !== undefined) return skin.art
  }
  const id = role.trim().toLowerCase()
  const exact = ROLE_ART[id] ?? ROLE_ART[agencyRole(role)?.executor ?? '']
  if (exact !== undefined) return art(exact)
  const identity = `${name} ${role}`.toLowerCase()
  for (const [pattern, file] of KEYWORD_ART) {
    if (pattern.test(identity)) return art(file)
  }
  return null
}
